-- Timestamps are ISO-8601 UTC text (e.g. 2026-01-31T12:00:00.000Z), the same
-- format as JavaScript's Date#toISOString(), so they sort and compare as text.
-- UUIDs are generated by the application.

-- ============================================
-- Tables
-- ============================================

-- USERS
CREATE TABLE IF NOT EXISTS users (
    user_id                   TEXT PRIMARY KEY,

    created_at                TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at                TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),

    -- Identity
    display_name              TEXT NOT NULL CHECK (length(display_name) <= 64),
    username                  TEXT NOT NULL COLLATE NOCASE,
    email                     TEXT COLLATE NOCASE,

    profile_pic_url           TEXT CHECK (length(profile_pic_url) <= 512),

    -- Auth
    hashed_password                 TEXT NOT NULL,
    password_changed_at             TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    token_version                   INTEGER NOT NULL DEFAULT 0,
    verified                        INTEGER NOT NULL DEFAULT 0 CHECK (verified IN (0, 1)),
    verify_token                    TEXT,
    verify_token_timestamp          TEXT,
    reset_password_token            TEXT,
    reset_password_token_timestamp  TEXT,
    disabled                        INTEGER NOT NULL DEFAULT 0 CHECK (disabled IN (0, 1)),

    CONSTRAINT users_username_uk UNIQUE (username),
    CONSTRAINT users_email_uk    UNIQUE (email),
    -- Equivalent to the regex ^[A-Za-z0-9_.-]{3,32}$
    CONSTRAINT users_username_chk CHECK (
        length(username) BETWEEN 3 AND 32 AND username NOT GLOB '*[^A-Za-z0-9_.-]*'
    ),
    CONSTRAINT users_email_chk    CHECK (instr(email, '@') > 1)
);

-- SYSTEM AGENTS
CREATE TABLE IF NOT EXISTS system_agents (
    agent_id     TEXT PRIMARY KEY,
    created_at   TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at   TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),

    display_name TEXT NOT NULL CHECK (length(display_name) <= 128),
    model_name   TEXT NOT NULL CHECK (length(model_name) <= 128),
    avatar_url   TEXT CHECK (length(avatar_url) <= 512),

    CONSTRAINT system_agents_display_name_uk UNIQUE (display_name),
    CONSTRAINT system_agents_model_name_uk UNIQUE (model_name)
);

-- CONVERSATIONS
CREATE TABLE IF NOT EXISTS conversations (
    convo_id    TEXT PRIMARY KEY,
    creator_id  TEXT REFERENCES users (user_id) ON DELETE CASCADE,
    created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    name        TEXT NOT NULL CHECK (length(name) <= 128)
);

-- MESSAGES
CREATE TABLE IF NOT EXISTS messages (
    message_id   TEXT PRIMARY KEY,
    created_at   TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at   TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),

    convo_id     TEXT NOT NULL,
    type         TEXT NOT NULL CHECK (type IN ('text', 'image')),

    sender_type   TEXT NOT NULL DEFAULT 'user' CHECK (sender_type IN ('user', 'anonymous', 'system')),
    sender_id     TEXT,
    sender_name   TEXT CHECK (length(sender_name) <= 64),
    sender_avatar TEXT CHECK (length(sender_avatar) <= 256),
    agent_id      TEXT,

    content      TEXT NOT NULL,

    CONSTRAINT messages_convo_fk
        FOREIGN KEY (convo_id) REFERENCES conversations (convo_id)
        ON DELETE CASCADE,

    CONSTRAINT messages_sender_fk
        FOREIGN KEY (sender_id) REFERENCES users (user_id)
        ON DELETE SET NULL,

    CONSTRAINT messages_agent_fk
        FOREIGN KEY (agent_id) REFERENCES system_agents (agent_id)
        ON DELETE SET NULL,

    CONSTRAINT messages_sender_type_chk CHECK (
        (sender_type = 'user'      AND sender_id IS NOT NULL AND agent_id IS NULL) OR
        (sender_type = 'anonymous' AND sender_id IS NULL     AND agent_id IS NULL) OR
        (sender_type = 'system'    AND sender_id IS NULL)
    ),

    -- Byte length, matching the in-app check that uses Buffer.byteLength
    CONSTRAINT messages_content_len_chk CHECK (length(CAST(content AS BLOB)) <= 4096)
);

-- SESSIONS
CREATE TABLE IF NOT EXISTS sessions (
    session_id      TEXT PRIMARY KEY,
    user_id         TEXT NOT NULL REFERENCES users (user_id) ON DELETE CASCADE,
    rt_hash         TEXT NOT NULL,              -- store a hash, never the raw token
    user_agent      TEXT,
    ip              TEXT,
    created_at      TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    expires_at      TEXT NOT NULL,
    revoked_at      TEXT
);

-- CONVERSATION VISITS (many-to-many: users <-> conversations)
CREATE TABLE IF NOT EXISTS conversation_visits (
    user_id     TEXT NOT NULL REFERENCES users (user_id) ON DELETE CASCADE,
    convo_id    TEXT NOT NULL REFERENCES conversations (convo_id) ON DELETE CASCADE,
    visited_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),

    PRIMARY KEY (user_id, convo_id)
);

-- ============================================
-- Indexes for common access patterns
-- ============================================
CREATE INDEX IF NOT EXISTS idx_messages_convo_id_created_at ON messages (convo_id, created_at);
CREATE INDEX IF NOT EXISTS idx_messages_sender_id ON messages (sender_id);
CREATE INDEX IF NOT EXISTS idx_messages_agent_id  ON messages (agent_id);

CREATE INDEX IF NOT EXISTS idx_conversations_creator_id ON conversations (creator_id);
CREATE INDEX IF NOT EXISTS idx_conversations_updated_at ON conversations (updated_at);
CREATE INDEX IF NOT EXISTS idx_sessions_user_id ON sessions (user_id);
CREATE INDEX IF NOT EXISTS idx_sessions_rt_hash ON sessions (rt_hash);
CREATE INDEX IF NOT EXISTS idx_conversation_visits_convo_id ON conversation_visits (convo_id);

-- ============================================
-- Triggers
-- ============================================
-- updated_at and token timestamps are set by the models in their own
-- INSERT/UPDATE statements, because SQLite's RETURNING clause does not
-- reflect changes made by AFTER triggers.

-- Bump a conversation's updated_at when its messages change, which keeps
-- active conversations from expiring.
CREATE TRIGGER IF NOT EXISTS trg_messages_touch_convo_ins
AFTER INSERT ON messages
BEGIN
    UPDATE conversations
       SET updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
     WHERE convo_id = NEW.convo_id;
END;

CREATE TRIGGER IF NOT EXISTS trg_messages_touch_convo_upd
AFTER UPDATE ON messages
BEGIN
    UPDATE conversations
       SET updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
     WHERE convo_id IN (OLD.convo_id, NEW.convo_id);
END;

CREATE TRIGGER IF NOT EXISTS trg_messages_touch_convo_del
AFTER DELETE ON messages
BEGIN
    UPDATE conversations
       SET updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
     WHERE convo_id = OLD.convo_id;
END;
